def insert_dash(num):
    num_str = str(num)
    result = []

    for i in range(len(num_str)):
        digit = int(num_str[i])
        result.append(num_str[i])

        if i < len(num_str) - 1:
            next_digit = int(num_str[i + 1])
            if digit % 2 != 0 and next_digit % 2 != 0:
                result.append('-')

    return ''.join(result)
